(()=>{'use strict';const logo='data:image/png;base64,';const xml=v=>String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));function lines(text,length){const words=String(text||'').split(/\s+/),out=[];let row='';for(const word of words){if(row&&row.length+word.length+1>length){out.push(row);row=word;}else row+=(row?' ':'')+word;}if(row)out.push(row);return out;}
function svg(w){const defaultPortrait=w.avatarKind==='male'?'data:image/png;base64,':'data:image/png;base64,';const portrait=`<image href="${/^data:image\/(jpeg|png|webp);base64,/.test(w.photo||'')?xml(w.photo):defaultPortrait}" x="790" y="78" width="216" height="252" preserveAspectRatio="xMidYMid meet"/>`;const name=lines(w.name,26),availability=lines(w.availability||'Verfügbarkeit noch offen',44),details=[w.role||'Reinigungskraft',w.employment&&w.employment!=='Noch offen'?w.employment:'Beschäftigung noch offen'];return `<svg xmlns="http://www.w3.org/2000/svg" width="1070" height="675" viewBox="0 0 1070 675"><defs><linearGradient id="portraitFadeGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="white"/><stop offset=".64" stop-color="white"/><stop offset=".74" stop-color="white" stop-opacity=".92"/><stop offset=".88" stop-color="white" stop-opacity=".5"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient><mask id="portraitFade" maskUnits="userSpaceOnUse" x="790" y="78" width="216" height="252"><rect x="790" y="78" width="216" height="252" fill="url(#portraitFadeGradient)"/></mask><linearGradient id="bg"><stop stop-color="#f8fcff"/><stop offset=".45" stop-color="#e7f3ff"/><stop offset="1" stop-color="#c7e3fc"/></linearGradient></defs><rect x="2" y="2" width="1066" height="671" rx="42" fill="url(#bg)" stroke="#97bce7" stroke-width="3"/><path d="M44 2h22v671H44A42 42 0 0 1 2 631V44A42 42 0 0 1 44 2" fill="#012e89"/><path d="M67 550Q520 570 810 2h255Q800 600 67 650" fill="#fff" opacity=".32"/>${portrait}<g font-family="Arial,Helvetica,sans-serif" fill="#012e89">${name.map((line,i)=>`<text x="118" y="${116+i*51}" font-size="44" font-weight="700">${xml(line)}</text>`).join('')}<text x="118" y="${126+name.length*51}" font-size="25">${xml(w.personalNumber||w.id)}</text>${details.map((line,i)=>`<text x="118" y="${245+i*37}" font-size="26">${xml(line)}</text>`).join('')}${availability.map((line,i)=>`<text x="118" y="${363+i*32}" font-size="24">${xml(line)}</text>`).join('')}<image href="${logo}" x="785" y="535" width="180" height="80" preserveAspectRatio="xMidYMid meet"/><text x="875" y="628" font-size="12" letter-spacing="2" text-anchor="middle">REINIGUNGSSERVICE</text></g></svg>`;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function png(w){const url=URL.createObjectURL(new Blob([svg(w)],{type:'image/svg+xml'}));try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const canvas=document.createElement('canvas');canvas.width=1070;canvas.height=675;canvas.getContext('2d').drawImage(image,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG nicht verfügbar');download(blob,'LISS-Badge-'+String(w.id).replace(/[^a-z0-9_-]/gi,'_')+'.png');}catch(e){alert('Badge konnte nicht exportiert werden. Bitte Druck / PDF verwenden.');}finally{URL.revokeObjectURL(url);}}
function print(w){const html='<!doctype html><html lang="de"><meta charset="utf-8"><title>LISS Badge · '+xml(w.name)+'</title><style>body{font:14px system-ui;background:#f4f7fc;padding:24px}svg{width:85.6mm;height:54mm;display:block;margin:24px 0}button{padding:10px 14px;background:#012e89;color:white;border:0;border-radius:8px}@media print{body{padding:0;background:white}button,p{display:none}svg{margin:0} @page{margin:15mm}}</style><button onclick="window.print()">Drucken / als PDF speichern</button><p>Badge · Originalgröße. Im Druckdialog Skalierung 100 % wählen.</p>'+svg(w)+'</html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html'})),tab=window.open(url,'_blank');if(!tab)download(new Blob([html],{type:'text/html'}),'LISS-Badge-'+w.id+'.html');setTimeout(()=>URL.revokeObjectURL(url),60000);}
window.LissBadgeExport={png,print};})();
